update public.spell_catalog set name_ru='Кислотная стрела', casting_time='Действие', spell_range='90 футов', area='1 цель', duration='Мгновенно', components=array['В','С','М'], material='измельчённый лист ревеня', check_type='Дальняя атака заклинанием', damage='4к4 кислотой при попадании; ещё 2к4 в конце следующего хода цели; при промахе — половина начального урона', effect_summary='Выпускаешь кислотную стрелу. При попадании цель получает начальный урон и ещё одну порцию кислоты в конце своего следующего хода. При промахе получает только половину начального урона.', upcast='+1к4 к начальному и отложенному урону за каждый уровень ячейки выше 2.', notes='Отложенный урон срабатывает только при попадании.', author_description='Кислота прилетает сейчас, а потом возвращается к вопросу чуть позже. Редкая магия, которая умеет напоминать о твоих ошибках лучше кредитора.', author_comment='Промахнулся? Не страшно. Кислота всё равно постарается сделать вид, что ты компетентен.' where slug='acid-arrow';
update public.spell_catalog set name_ru='Подмога', casting_time='Действие', spell_range='30 футов', area='До 3 существ', duration='8 часов', components=array['В','С','М'], material='полоска белой ткани', check_type='', damage='Лечение/максимум HP: +5', effect_summary='До трёх существ увеличивают текущие и максимальные HP на 5 на 8 часов.', upcast='+5 HP за каждый уровень ячейки выше 2.', notes='Это увеличение максимума HP, а не временные HP.', author_description='Трое становятся чуть менее хрупкими на восемь часов. Жрец потом обязательно объяснит, что это благословение. Воин назвал бы это хорошей подготовкой.', author_comment='Пять лишних HP — это примерно одна ошибка, которую партия может позволить себе бесплатно.' where slug='aid';
update public.spell_catalog set name_ru='Изменение облика', casting_time='Действие', spell_range='На себя', area='На себя', duration='Концентрация, до 1 часа', components=array['В','С'], material=null, check_type='', damage='Природное оружие: 1к6', effect_summary='Выбираешь одно из трёх изменений: жабры и скорость плавания; изменение внешности и голоса без смены размера и базовой формы; либо природное оружие 1к6 с использованием характеристики заклинаний. Действием Магии можно менять выбранный вариант.', upcast='', notes='Изменение внешности не меняет характеристики и не позволяет стать существом другого размера или иной базовой формы.', author_description='Можно отрастить жабры, поменять лицо или наконец обзавестись когтями. Магия предлагает три способа решить проблему, и ни один не включает нормальный разговор.', author_comment='Если после третьей смены лица стража всё ещё тебя узнаёт — возможно, дело уже не во внешности.' where slug='alter-self';
update public.spell_catalog set name_ru='Животный посланник', casting_time='Действие', spell_range='30 футов', area='1 крошечный зверь', duration='24 часа', components=array['В','С','М'], material='кусочек еды', check_type='Спасбросок Харизмы; зверь с CR выше 0 автоматически преуспевает', damage='', effect_summary='Поручаешь крошечному зверю доставить сообщение до 25 слов в знакомое место существу по общему описанию. Зверь идёт около 25 миль в сутки или 50 миль, если летает.', upcast='+48 часов длительности за каждый уровень ячейки выше 2.', notes='Если зверь не добрался до конца действия, сообщение теряется и он возвращается. Подходят только крошечные звери; зверь с CR выше 0 автоматически отвергает поручение.', author_description='Платишь зверьку едой, объясняешь адрес и отправляешь его работать курьером. Следопыты называют это природной связью. Нормальные люди — очень сомнительной службой доставки.', author_comment='Если сообщение не дошло, возможно, голубь просто первым понял, что ваша партия обречена.' where slug='animal-messenger';
update public.spell_catalog set name_ru='Волшебный замок', casting_time='Действие', spell_range='Касание', area='Закрытая дверь, окно, ворота, контейнер или люк', duration='До рассеивания', components=array['В','С','М'], material='золотая пыль стоимостью 25+ зм, расходуется', check_type='', damage='', effect_summary='Магически запирает закрываемый объект. Немагическими средствами открыть его нельзя. При наложении можно назначить существ, которые открывают его свободно, и пароль, снимающий запирание на 1 минуту.', upcast='', notes='Материал расходуется. Заклинание «Стук» временно подавляет этот замок.', author_description='Дорогой способ сказать «не входить». Дешевле замка, возможно, только табличка. Но табличка хуже переживает плутов.', author_comment='Если в партии есть плут, пароль лучше не произносить даже во сне.' where slug='arcane-lock';
update public.spell_catalog set name_ru='Магическая аура арканиста', casting_time='Действие', spell_range='Касание', area='1 добровольное существо или непереносимый объект', duration='24 часа', components=array['В','С','М'], material='маленький квадрат шёлка', check_type='', damage='', effect_summary='На существе можно замаскировать его тип для заклинаний и магических эффектов. На объекте можно подделать магическую ауру: скрыть магию, изобразить её или сменить видимую школу. Ежедневное наложение 30 дней делает эффект постоянным до рассеивания.', upcast='', notes='Существо должно быть добровольным; объект не должен быть надет или переноситься.', author_description='Магическая косметика для тех, кому мало врать обычными словами. Теперь можно врать ещё и заклинаниям обнаружения.', author_comment='Тридцать дней подряд подделывать ауру — это уже не иллюзия. Это бухгалтерия.' where slug='arcanist-s-magic-aura';
update public.spell_catalog set name_ru='Предзнаменование', casting_time='Действие', spell_range='На себя', area='На себя', duration='Мгновенно', components=array['В','С','М'], material='особые отмеченные палочки, кости, карты или другие предметы для гадания стоимостью 25+ зм', check_type='', damage='', effect_summary='Получаешь от потусторонней сущности предзнаменование о действии, которое планируешь совершить в ближайшие 30 минут: благо, беда, и то и другое или ничего особенного.', upcast='', notes='Не учитывает обстоятельства, которые позже изменят результат. После первого применения до долгого отдыха каждое следующее имеет накопительный шанс 25% не дать ответа.', author_description='Спрашиваешь вселенную, хорошая ли у тебя идея. Полезно, если рядом нет следопыта, который мог бы бесплатно сказать, что идея идиотская.', author_comment='Чем чаще спрашиваешь судьбу, тем выше шанс, что даже судьба перестанет отвечать.' where slug='augury';
update public.spell_catalog set name_ru='Дубовая кожа', casting_time='Бонусное действие', spell_range='Касание', area='1 добровольное существо', duration='1 час', components=array['В','С','М'], material='горсть коры', check_type='', damage='', effect_summary='Кожа цели становится похожей на кору. Если её КД ниже 17, он становится 17 на время действия.', upcast='', notes='Не требует концентрации. Не повышает КД, если он уже 17 или выше.', author_description='Друид превращает кожу в кору и называет это защитой природы. В лесу это обычно называется «быть деревом», но пусть у них будет праздник.', author_comment='Выглядишь как шкаф, зато теперь примерно так же трудно пробить.' where slug='barkskin';
update public.spell_catalog set name_ru='Слепота/Глухота', casting_time='Действие', spell_range='120 футов', area='1 существо', duration='1 минута', components=array['В'], material=null, check_type='Спасбросок Телосложения', damage='', effect_summary='При провале цель становится Ослеплённой или Оглохшей на выбор. В конце каждого своего хода она повторяет спасбросок, заканчивая эффект при успехе.', upcast='+1 цель за каждый уровень ячейки выше 2.', notes='Не требует концентрации.', author_description='Можно выключить человеку зрение или слух. Почему нельзя выключить барду рот — вопрос, который магическая наука упорно игнорирует.', author_comment='Глухота иногда выглядит не как проклятие, а как разумная реакция на группу приключенцев.' where slug='blindness-deafness';
update public.spell_catalog set name_ru='Размытие', casting_time='Действие', spell_range='На себя', area='На себя', duration='Концентрация, до 1 минуты', components=array['В'], material=null, check_type='', damage='', effect_summary='Твоё тело расплывается для наблюдателей. Атаки по тебе совершаются с помехой.', upcast='', notes='Не действует против атакующего, который воспринимает тебя слепым зрением или истинным зрением.', author_description='Делаешь себя визуально неудобным для попадания. Наконец магия признаёт главное правило выживания: лучше, чтобы били кого-то другого.', author_comment='Если противник видит без глаз, размытие уже не самая большая твоя проблема.' where slug='blur';
update public.spell_catalog set name_ru='Умиротворение', casting_time='Действие', spell_range='60 футов', area='Сфера радиусом 20 футов', duration='Концентрация, до 1 минуты', components=array['В','С'], material=null, check_type='Спасбросок Харизмы', damage='', effect_summary='Каждый гуманоид в области при провале спасброска либо временно получает иммунитет к Очарованию и Испугу с подавлением уже существующих состояний, либо становится Безразличным к выбранным враждебным существам.', upcast='', notes='Безразличие заканчивается, если цель получает урон или видит, как её союзникам наносят урон. После окончания отношение возвращается к обычному.', author_description='На минуту заставляешь комнату вести себя как взрослые люди. Магия настолько фантастическая, что относится к Очарованию.', author_comment='Если переговоры держатся только на концентрации заклинателя, это не мир. Это пауза.' where slug='calm-emotions';
update public.spell_catalog set name_ru='Вечное пламя', casting_time='Действие', spell_range='Касание', area='1 объект', duration='До рассеивания', components=array['В','С','М'], material='рубиновая пыль стоимостью 50+ зм, расходуется', check_type='', damage='', effect_summary='На предмете появляется пламя без жара и топлива. Оно даёт яркий свет на 20 футов и тусклый ещё на 20. Его можно закрыть, но нельзя задуть или залить.', upcast='', notes='Материал расходуется. Пламя не наносит урон и не поджигает.', author_description='Пятьдесят золотых за лампу, которая никогда не гаснет. Волшебники наконец изобрели фонарь и, разумеется, сделали его дорогим.', author_comment='Не греет, не готовит еду, зато красиво. Почти как большинство придворных магов.' where slug='continual-flame';
update public.spell_catalog set name_ru='Тьма', casting_time='Действие', spell_range='60 футов', area='Сфера радиусом 15 футов или эманация от объекта', duration='Концентрация, до 10 минут', components=array['В','М'], material='мех летучей мыши и кусочек угля', check_type='', damage='', effect_summary='Создаёт магическую тьму, через которую не видит обычное тёмное зрение и которую не освещает немагический свет. Можно наложить на непереносимый объект и затем закрывать источник непрозрачной оболочкой.', upcast='', notes='Если область пересекается с ярким или тусклым светом от заклинания 2 уровня или ниже, то заклинание света рассеивается.', author_description='Выключает свет настолько убедительно, что даже тёмное зрение сдаётся. Варлоки обычно называют это «создать комфортную рабочую обстановку».', author_comment='Если ты сам не видишь в собственной Тьме, поздравляю: ты просто выключил свет во время драки.' where slug='darkness';
update public.spell_catalog set name_ru='Тёмное зрение', casting_time='Действие', spell_range='Касание', area='1 добровольное существо', duration='8 часов', components=array['В','С','М'], material='сушёная морковь', check_type='', damage='', effect_summary='Даёт цели тёмное зрение на 150 футов на 8 часов.', upcast='', notes='Не требует концентрации.', author_description='Касаешься союзника с морковкой и на восемь часов исправляешь его неспособность видеть ночью. Иногда магия действительно решает проблему без взрыва.', author_comment='Сто пятьдесят футов тёмного зрения. Всё ещё не помогает замечать очевидные плохие решения.' where slug='darkvision';
update public.spell_catalog set name_ru='Обнаружение мыслей', casting_time='Действие', spell_range='На себя', area='Мысли в пределах 30 футов', duration='Концентрация, до 1 минуты', components=array['В','С','М'], material='медная монета', check_type='Глубокое чтение: спасбросок Мудрости; сопротивление после обнаружения: Интеллект (Магия) против Сл спасброска заклинаний', damage='', effect_summary='Позволяет ощущать присутствие мыслящих существ, знающих язык или обладающих телепатией, в 30 футах. Можно читать поверхностные мысли выбранной цели и затем попытаться проникнуть глубже.', upcast='', notes='Камень/земля/дерево толщиной 1 фут, металл 1 дюйм или тонкий лист свинца блокируют эффект. При попытке глубокого чтения цель узнаёт о вторжении.', author_description='Сначала узнаёшь, что рядом кто-то думает. Потом узнаёшь что именно. Последний этап обычно и является причиной, почему это заклинание не стоит применять на друзьях.', author_comment='Ты всегда хотел знать, что люди думают о тебе. Это была ошибка.' where slug='detect-thoughts';
update public.spell_catalog set name_ru='Драконье дыхание', casting_time='Бонусное действие', spell_range='Касание', area='1 добровольное существо; затем конус 15 футов', duration='Концентрация, до 1 минуты', components=array['В','С','М'], material='острый перец', check_type='Спасбросок Ловкости', damage='3к6 кислотой, холодом, огнём, электричеством или ядом; половина при успехе', effect_summary='Выбираешь тип урона и наделяешь цель способностью действием Магии выдыхать 15-футовый конус. Существа в конусе делают спасбросок Ловкости.', upcast='+1к6 урона за каждый уровень ячейки выше 2.', notes='Тип урона выбирается при наложении.', author_description='Даёшь кому-то возможность дышать огнём, кислотой или ещё чем-нибудь неприятным. Природа драконов наконец сведена к острому перцу и плохой идее.', author_comment='Никогда не давай это тому, кто сначала спрашивает: «А своих заденет?»' where slug='dragon-s-breath';
update public.spell_catalog set name_ru='Усиление характеристики', casting_time='Действие', spell_range='Касание', area='1 существо', duration='Концентрация, до 1 часа', components=array['В','С','М'], material='мех или перо', check_type='', damage='', effect_summary='Выбираешь Силу, Ловкость, Интеллект, Мудрость или Харизму. Цель получает преимущество на проверки выбранной характеристики.', upcast='+1 цель за каждый уровень ячейки выше 2; для каждой можно выбрать свою характеристику.', notes='Не влияет напрямую на спасброски и броски атаки — только на проверки характеристик.', author_description='На час делаешь кого-то заметно компетентнее в одной области. Жаль, что нельзя выбрать характеристику «здравый смысл».', author_comment='Если после преимущества человек всё равно провалил проверку — это уже талант.' where slug='enhance-ability';
update public.spell_catalog set name_ru='Увеличение/Уменьшение', casting_time='Действие', spell_range='30 футов', area='1 существо или непереносимый объект', duration='Концентрация, до 1 минуты', components=array['В','С','М'], material='щепотка железного порошка', check_type='Нежелающее существо: спасбросок Телосложения', damage='Увеличение: +1к4 к урону оружием/безоружным ударом; уменьшение: −1к4, минимум 1', effect_summary='Увеличивает или уменьшает цель на одну категорию размера. Увеличенная цель получает преимущество на проверки и спасброски Силы и +1к4 к урону; уменьшенная — помеху и −1к4 к урону.', upcast='', notes='Надетые и переносимые предметы меняются вместе с существом, но возвращаются к нормальному размеру после выбрасывания. Боеприпасы и метательное оружие возвращаются к размеру сразу после попадания или промаха.', author_description='Магия для тех, кто считает, что любую проблему можно решить, если сделать союзника больше или врага меньше. Неприятно признавать, но иногда они правы.', author_comment='Да, увеличенный варвар всё ещё помещается в дверной проём. Обычно вместе с дверным проёмом.' where slug='enlarge-reduce';
update public.spell_catalog set name_ru='Заворожить', casting_time='Действие', spell_range='60 футов', area='Выбранные видимые существа', duration='Концентрация, до 1 минуты', components=array['В','С'], material=null, check_type='Спасбросок Мудрости', damage='', effect_summary='Выбранные существа при провале получают штраф −10 к проверкам Мудрости (Восприятие) и пассивному Восприятию.', upcast='', notes='Существа, с которыми ты или союзники сражаетесь, автоматически преуспевают в спасброске.', author_description='Говоришь настолько отвлекающе, что окружающие перестают нормально замечать мир. Барды называют это чарами. Остальные — обычным вторником рядом с бардом.', author_comment='−10 к Восприятию. Примерно тот же эффект даёт очень длинная история барда о самом себе.' where slug='enthrall';
update public.spell_catalog set name_ru='Поиск скакуна', casting_time='Действие', spell_range='30 футов', area='Свободное пространство', duration='Мгновенно', components=array['В','С'], material=null, check_type='', damage='', effect_summary='Призывает верного потустороннего скакуна выбранного облика. При каждом применении выбираешь тип существа: Небожитель, Фея или Исчадие. Он использует отдельный блок характеристик, действует как союзник и обычно служит управляемым верховым животным.', upcast='Уровень потраченной ячейки используется как уровень заклинания в блоке характеристик скакуна.', notes='Одновременно может существовать только один скакун от этого заклинания: новый заменяет старого. Он исчезает при 0 HP или смерти заклинателя.', author_description='Паладин зовёт верного магического скакуна, потому что обычная лошадь, видимо, недостаточно торжественно смотрится рядом с клятвами и сиянием.', author_comment='Скакун исчезает, если ты умер. Приятно знать, что хотя бы кто-то вовремя покидает провальную экспедицию.' where slug='find-steed';